const PATCHES=Object.freeze([{id:'sheep-west-meadow',kind:'sheep',x:-43,z:-39,phase:.2,range:2.1},{id:'sheep-north-meadow',kind:'sheep',x:43,z:45,phase:2.4,range:1.9},{id:'rabbit-west-meadow',kind:'rabbit',x:-44,z:34,phase:1.1,range:1.55},{id:'rabbit-east-meadow',kind:'rabbit',x:44,z:-40,phase:3.2,range:1.65}]);
export function faunaRoutine(seconds,phase,range,kind='sheep',hour=12){const resting=hour<5||hour>=21,pace=resting?.08:kind==='rabbit'?.42:.16,t=seconds*pace+phase,scale=resting?.13:1;return {offsetX:Math.sin(t)*range*scale,offsetZ:Math.sin(t*.73+phase)*range*.55*scale,heading:Math.atan2(Math.cos(t)*pace*range,Math.cos(t*.73+phase)*pace*range*.4),grazing:resting?.16:kind==='sheep'?.5+.5*Math.sin(t*1.65):.12+.12*Math.sin(t*2.1),hop:resting||kind!=='rabbit'?0:Math.pow(Math.max(0,Math.sin(t*2.65)),10)*.18,bodyBob:kind==='sheep'?Math.sin(t*2)*.018:0,resting,activity:resting?'Rest':kind==='sheep'?'Graze':'Forage'};}
function paint(B,mesh,hex){const c=B.Color3.FromHexString(hex),count=mesh.getTotalVertices(),colors=new Float32Array(count*4);for(let i=0;i<count;i++){colors[i*4]=c.r;colors[i*4+1]=c.g;colors[i*4+2]=c.b;colors[i*4+3]=1;}mesh.setVerticesData(B.VertexBuffer.ColorKind,colors,false,4);}
export function createAmbientFauna(B,scene,{heightAt=(x,z)=>0,shadows=null,patches=PATCHES}={}){
 const material=new B.StandardMaterial('Shire fauna vertex colours',scene);material.diffuseColor=B.Color3.White();material.specularColor=new B.Color3(.025,.025,.025);material.useVertexColors=true;
 const parts=[],add=(name,pos,scale,color)=>{const m=B.MeshBuilder.CreateSphere(name,{diameter:1,segments:8},scene);m.position.set(...pos);m.scaling.set(...scale);m.material=material;m.isPickable=false;paint(B,m,color);parts.push(m);};
 add('farm animal wool body',[0,.43,0],[.82,.5,.58],'#e7dfca');
 add('farm animal shoulder fleece',[-.19,.63,0],[.42,.32,.43],'#f0e8d6');
 add('farm animal head',[.43,.65,0],[.28,.28,.25],'#96714d');
 add('farm animal muzzle',[.55,.56,-.15],[.16,.12,.15],'#c4a47c');
 add('farm animal left ear',[.32,.87,-.13],[.085,.19,.07],'#96714d');
 add('farm animal right ear',[.32,.87,.13],[.085,.19,.07],'#96714d');
 add('farm animal tail',[-.47,.49,0],[.17,.17,.17],'#e7dfca');
 for(const [x,z] of [[-.27,-.2],[-.27,.2],[.27,-.2],[.27,.2]]){const leg=B.MeshBuilder.CreateCylinder('farm animal leg',{diameter:.075,height:.29,tessellation:6},scene);leg.position.set(x,.16,z);leg.material=material;leg.isPickable=false;paint(B,leg,'#51473d');parts.push(leg);}
 const mesh=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);if(!mesh)throw Error('Unable to merge Shire fauna geometry');mesh.name='shared low-poly Shire farm animal';mesh.material=material;mesh.isPickable=false;mesh.receiveShadows=true;
 const matrices=new Float32Array(patches.length*16),animals=patches.map((p,index)=>{const scale=p.kind==='sheep'?1:.72,position=new B.Vector3(p.x,heightAt(p.x,p.z),p.z),rotation=B.Quaternion.Identity(),matrix=B.Matrix.Compose(new B.Vector3(scale,scale,scale),rotation,position);matrix.copyToArray(matrices,index*16);return {...p,index,home:{x:p.x,z:p.z},activity:'Idle',scale};});
 mesh.thinInstanceSetBuffer('matrix',matrices,16,true);mesh.thinInstanceCount=animals.length;mesh.alwaysSelectAsActiveMesh=true;shadows?.addShadowCaster(mesh);
 return {mesh,animals,update(poses){for(const a of animals){const p=poses.get(a.id);if(!p)continue;const position=new B.Vector3(a.home.x+p.offsetX,heightAt(a.home.x+p.offsetX,a.home.z+p.offsetZ)+p.bodyBob+p.hop,a.home.z+p.offsetZ),rotation=B.Quaternion.RotationYawPitchRoll(p.heading,a.kind==='sheep'?p.grazing*.035:0,0),matrix=B.Matrix.Compose(new B.Vector3(a.scale,a.scale,a.scale),rotation,position);mesh.thinInstanceSetMatrixAt(a.index,matrix,false);a.activity=p.activity;}mesh.thinInstanceBufferUpdated('matrix');},dispose(){mesh.dispose();material.dispose();}};
}
